package com.autocare.platform.order;

import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class JdbcDiagnosisNotificationsTest extends JdbcDiagnosisCasesTest {
 DiagnosisNotifications notices;
 @BeforeEach void notices(){jdbc.execute("DROP TRIGGER IF EXISTS fail_diagnosis_notice");notices=new DiagnosisNotifications(db,servicePolicy);}
 @AfterEach void noticeCleanup(){jdbc.execute("DROP TRIGGER IF EXISTS fail_diagnosis_notice");}
 com.fasterxml.jackson.databind.JsonNode inbox(Object a){return json.valueToTree(notices.list(a,1));}
 long notice(Object a){return inbox(a).path("notifications").path("items").get(0).path("notification_id").asLong();}
 long created(){eligible();return submit(configure("AVAILABLE"));}
 int notices(String sql,Object...args){return jdbc.queryForObject(sql,Integer.class,args);}
 @Test void allFiveActualEventsAreAtomicMinimalAndPurposeBound(){
  eligible();long p=configure("AVAILABLE"),id=submit(p);String k=key();cases.assign(manager,id,k,assign(1,handlerA.id()));cases.assign(manager,id,k,assign(1,handlerA.id()));cases.write(handlerA,id,"reply",key(),text(2,"合成诊断答复"));cases.write(owner,id,"message",key(),follow(3,p));cases.write(owner,id,"close",key(),json.createObjectNode().put("expected_revision",4));
  assertEquals(5,count("diagnosis_notification_outbox"));assertEquals(19,count("diagnosis_notification_target"));notices.recover();notices.recover();assertEquals(19,count("notification"));assertEquals(5,inbox(owner).path("unread_count").asInt());assertEquals(4,inbox(handlerA).path("unread_count").asInt());assertEquals(5,inbox(manager).path("unread_count").asInt());
  for(var n:inbox(manager).path("notifications").path("items")){assertEquals("QUEUE",n.path("target").asText());assertEquals("CLOSED",n.path("case_status").asText());}
  for(var n:inbox(handlerA).path("notifications").path("items"))assertEquals("CASE",n.path("target").asText());
  String result=inbox(owner).toString()+inbox(manager);for(String forbidden:List.of("owner_id","operator_id","vehicle","body","payload","本次主动","合成诊断答复"))assertFalse(result.contains(forbidden));assertEquals(0,notices("SELECT COUNT(*) FROM notification WHERE payload IS NOT NULL"));assertEquals(403,code(()->cases.detail(manager,id,1)));
 }
 @Test void transferRevalidatesCachedReadsAndDoesNotGiveNewHandlerOldNotices(){
  long id=created();cases.assign(manager,id,key(),assign(1,handlerA.id()));notices.recover();long old=notice(handlerA);String k=key();notices.read(handlerA,old,k);cases.assign(manager,id,key(),assign(2,handlerB.id()));new DiagnosisNotifications(db,servicePolicy).recover();assertEquals(0,inbox(handlerA).path("notifications").path("total").asInt());assertEquals(1,inbox(handlerB).path("unread_count").asInt());assertEquals(404,code(()->notices.read(handlerA,old,k)));assertEquals(404,code(()->notices.read(handlerB,old,key())));
 }
 @Test void dualPermissionDegradesToQueueWithoutPromotingOldManagerPurpose(){
  jdbc.update("UPDATE operator_account SET can_diagnose_manage=1 WHERE id=?",handlerA.id());long id=created();notices.recover();assertEquals("QUEUE",inbox(handlerA).path("notifications").path("items").get(0).path("target").asText());cases.assign(manager,id,key(),assign(1,handlerA.id()));notices.recover();var items=inbox(handlerA).path("notifications").path("items");assertEquals("CASE",items.get(0).path("target").asText());assertEquals("QUEUE",items.get(1).path("target").asText());long n=notice(handlerA);String k=key();notices.read(handlerA,n,k);jdbc.update("UPDATE operator_account SET can_diagnose=0 WHERE id=?",handlerA.id());notices.read(handlerA,n,k);for(var row:inbox(handlerA).path("notifications").path("items"))assertEquals("QUEUE",row.path("target").asText());assertEquals(403,code(()->cases.detail(handlerA,id,1)));jdbc.update("UPDATE operator_account SET can_diagnose_manage=0 WHERE id=?",handlerA.id());assertEquals(403,code(()->notices.read(handlerA,n,k)));
 }
 @Test void disabledRolesSessionsAndCrossOwnerCannotUseNotificationHistory(){
  long id=created();cases.assign(manager,id,key(),assign(1,handlerA.id()));notices.recover();long n=notice(owner);assertEquals(0,inbox(peer).path("unread_count").asInt());assertEquals(404,code(()->notices.read(peer,n,key())));assertEquals(404,code(()->notices.read(manager,n,key())));jdbc.update("UPDATE operator_account SET status='DISABLED' WHERE id=?",handlerA.id());assertEquals(401,code(()->notices.list(handlerA,1)));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->notices.read(owner,n,key())));
 }
 @Test void recipientWriteFailureRollsBackMessageCaseEventAndOriginalKey(){
  eligible();long p=configure("AVAILABLE");String k=key();jdbc.execute("CREATE TRIGGER fail_diagnosis_notice BEFORE INSERT ON diagnosis_notification_target FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");try{assertEquals(503,code(()->cases.create(owner,k,question(p))));for(String t:List.of("diagnosis_case","diagnosis_message","diagnosis_case_event","diagnosis_notification_outbox","diagnosis_notification_target"))assertEquals(0,count(t));}finally{jdbc.execute("DROP TRIGGER fail_diagnosis_notice");}cases.create(owner,k,question(p));cases.create(owner,k,question(p));assertEquals(1,count("diagnosis_case"));assertEquals(1,count("diagnosis_notification_outbox"));
 }
 @Test void failedFanoutIsAtomicAndLaterEventsStillDeliverAfterRestart(){
  long id=created();cases.assign(manager,id,key(),assign(1,handlerA.id()));jdbc.execute("CREATE TRIGGER fail_diagnosis_notice BEFORE INSERT ON notification FOR EACH ROW BEGIN IF NEW.template_key='DIAGNOSIS_CREATED' AND NEW.recipient_type='user' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'; END IF; END");notices.recover();assertEquals(4,count("notification"));assertEquals(1,notices("SELECT attempts FROM diagnosis_notification_outbox WHERE kind='DIAGNOSIS_CREATED'"));assertEquals("DELIVERY_UNAVAILABLE",jdbc.queryForObject("SELECT last_error FROM diagnosis_notification_outbox WHERE kind='DIAGNOSIS_CREATED'",String.class));jdbc.execute("DROP TRIGGER fail_diagnosis_notice");clock.value=clock.value.plusSeconds(301);new DiagnosisNotifications(db,servicePolicy).recover();assertEquals(7,count("notification"));assertEquals(2,notices("SELECT COUNT(*) FROM diagnosis_notification_outbox WHERE status='DONE'"));
 }
 @Test void concurrentWorkersDeliverOneCompleteRecipientSet()throws Exception{
  created();long id=jdbc.queryForObject("SELECT id FROM diagnosis_notification_outbox",Long.class);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return notices.deliver(id);});var b=pool.submit(()->{start.await();return new DiagnosisNotifications(db,servicePolicy).deliver(id);});start.countDown();assertNotEquals(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));assertEquals(3,count("notification"));}finally{pool.shutdownNow();}
 }
 @Test void readIsIdempotentAndAuditFailureLeavesUnread(){
  created();notices.recover();long n=notice(owner);String k=key();int before=count("audit_log");var r=notices.read(owner,n,k);clock.value=clock.value.plusSeconds(5);assertEquals(r,notices.read(owner,n,k));assertEquals(r.path("data"),notices.read(owner,n,key()).path("data"));assertEquals(before+1,count("audit_log"));assertEquals(0,inbox(owner).path("unread_count").asInt());long other=notice(manager);jdbc.execute("CREATE TRIGGER fail_diagnosis_notice BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->notices.read(manager,other,key())));assertNull(jdbc.queryForObject("SELECT read_at FROM notification WHERE id=?",Object.class,other));
 }
 @Test void paginationAndCurrentOwnerCountsUseTheSameScope(){
  eligible();long p=configure("AVAILABLE");for(int i=0;i<21;i++)submit(p);notices.recover();notices.recover();assertEquals(21,inbox(owner).path("notifications").path("total").asInt());assertEquals(20,inbox(owner).path("notifications").path("items").size());assertEquals(1,json.valueToTree(notices.list(owner,2)).path("notifications").path("items").size());jdbc.update("UPDATE diagnosis_case SET owner_id=2 WHERE id=(SELECT x.id FROM (SELECT MIN(id) AS id FROM diagnosis_case) x)");assertEquals(20,inbox(owner).path("unread_count").asInt());assertEquals(0,inbox(peer).path("notifications").path("total").asInt());
 }
 @Test void migrationNeverBackfillsAndRepeatEnqueueKeepsCapturedRecipients()throws Exception{
  long id=created();int targets=count("diagnosis_notification_target");jdbc.update("UPDATE operator_account SET can_diagnose_manage=1 WHERE id=?",handlerA.id());db.transactions.executeWithoutResult(tx->{servicePolicy.guard();DiagnosisNotifications.enqueue(db,id,1,"CREATED");});assertEquals(targets,count("diagnosis_notification_target"));jdbc.update("DELETE FROM diagnosis_notification_target");jdbc.update("DELETE FROM diagnosis_notification_outbox");try(var c=jdbc.getDataSource().getConnection()){for(int i=0;i<2;i++)org.springframework.jdbc.datasource.init.ScriptUtils.executeSqlScript(c,new org.springframework.core.io.FileSystemResource(java.nio.file.Path.of("..","docs","sql","migrations","V048__diagnosis_notifications.sql")));}notices.recover();assertEquals(0,count("notification"));assertEquals(0,count("diagnosis_notification_outbox"));cases.assign(manager,id,key(),assign(1,handlerB.id()));notices.recover();assertEquals(1,count("diagnosis_notification_outbox"));assertEquals(1,inbox(handlerB).path("unread_count").asInt());
 }
 @Test void concurrentReadAndReplyFollowTheSameControlLockOrder()throws Exception{
  long id=created();cases.assign(manager,id,key(),assign(1,handlerA.id()));notices.recover();long n=notice(handlerA);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var a=pool.submit(()->{start.await();return notices.read(handlerA,n,key());});var b=pool.submit(()->{start.await();return cases.write(handlerA,id,"reply",key(),text(2,"并发合成答复"));});start.countDown();a.get(30,TimeUnit.SECONDS);b.get(30,TimeUnit.SECONDS);assertEquals(3,notices("SELECT revision FROM diagnosis_case WHERE id=?",id));assertNotNull(jdbc.queryForObject("SELECT read_at FROM notification WHERE id=?",Object.class,n));}finally{pool.shutdownNow();}
 }
 @Test void currentManagerCaptureDoesNotReuseEarlierReadView()throws Exception{
  long id=created();var pool=Executors.newSingleThreadExecutor();try{db.transactions.executeWithoutResult(tx->{servicePolicy.guard();assertEquals(0,notices("SELECT can_diagnose_manage FROM operator_account WHERE id=?",handlerA.id()));try{pool.submit(()->jdbc.update("UPDATE operator_account SET can_diagnose_manage=1 WHERE id=?",handlerA.id())).get(10,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}jdbc.update("UPDATE diagnosis_case SET revision=2,status='CLOSED' WHERE id=?",id);jdbc.update("INSERT INTO diagnosis_case_event(case_id,case_revision,kind,occurred_at) VALUES(?,2,'CLOSED',?)",id,ReservationStore.time(clock.value));DiagnosisNotifications.enqueue(db,id,2,"CLOSED");});}finally{pool.shutdownNow();}assertEquals(1,notices("SELECT COUNT(*) FROM diagnosis_notification_target t JOIN diagnosis_notification_outbox e ON e.id=t.outbox_id WHERE e.case_revision=2 AND t.recipient_type='operator_account' AND t.recipient_id=? AND t.can_queue=1 AND t.can_detail=0",handlerA.id()));
 }
}
